/**
 * snapshot.ts — Runtime access to the build-time content snapshot.
 *
 * The snapshot is generated by scripts/build-content.mjs (predev / prebuild)
 * and written to src/data/generated/snapshot.json. It contains already-adapted
 * public types (camelCase, I18nString). This module just imports and re-exports
 * it with proper typing.
 *
 * The snapshot is small (< 100 kB gzipped) so it is imported statically —
 * no extra network request for first paint. If it ever exceeds 100 kB,
 * switch to a dynamic import() for a lazy chunk.
 */

import type {
  Announcement,
  CommitteeMember,
  Edition,
  EventItem,
  FAQ,
  GalleryItem,
  NewsItem,
  Sponsor,
} from '../types';

export interface SiteSettingsSnapshot {
  contactEmail: string | null;
  phone: string | null;
  addressI18n: { en: string; am?: string; om?: string } | null;
  social: Record<string, string> | null;
  footerTextI18n: { en: string; am?: string; om?: string } | null;
}

// ── Added in Phase 6B ──────────────────────────────────────────────────────

/** Adapted page section item (camelCase) as stored in the snapshot. */
export interface SectionItemSnapshot {
  id: string;
  sectionId: string;
  titleI18n:  { en: string; am: string; om: string } | null;
  bodyI18n:   { en: string; am: string; om: string } | null;
  icon:       string | null;
  imageUrl:   string | null;
  linkUrl:    string | null;
  badgeI18n:  { en: string; am: string; om: string } | null;
  sortOrder:  number;
  state:      'draft' | 'published';
}

/** Adapted page section (camelCase) as stored in the snapshot. */
export interface SectionSnapshot {
  id:            string;
  key:           string;
  titleI18n:     { en: string; am: string; om: string } | null;
  subtitleI18n:  { en: string; am: string; om: string } | null;
  bodyI18n:      { en: string; am: string; om: string } | null;
  imageUrl:      string | null;
  ctaLabelI18n:  { en: string; am: string; om: string } | null;
  ctaUrl:        string | null;
  state:         'draft' | 'published';
  needsReview:   boolean;
  items:         SectionItemSnapshot[];
}

/**
 * Past edition as stored in the snapshot.
 * Extends the base Edition type with Phase 6B fields and 017 fields.
 */
export interface PastEditionSnapshot extends Edition {
  subtitleI18n:       { en: string; am: string; om: string } | null;
  themeHighlightI18n: { en: string; am: string; om: string } | null;
  heroPosterUrl:      string | null;
  heroVideoUrl:       string | null;
  summaryI18n:        { en: string; am: string; om: string } | null;
  coverImageUrl:      string | null;
  state:              'draft' | 'published';
  /** Added in migration 017. */
  logoUrl:            string | null;
  /** Added in migration 017. */
  aboutI18n:          { en: string; am: string; om: string } | null;
}

/** Adapted edition-day row as stored in the snapshot. Added in migration 017. */
export interface EditionDaySnapshot {
  id:              string;
  editionId:       string;
  day:             number;
  titleI18n:       { en: string; am: string; om: string } | null;
  descriptionI18n: { en: string; am: string; om: string } | null;
}

/** Public contact block embedded in a committee member snapshot when show_public=true. */
export interface CommitteeMemberContactSnapshot {
  email:    string | null;
  phone:    string | null;
  telegram: string | null;
}

export interface Snapshot {
  generatedAt: string;
  source: 'supabase' | 'last-good' | 'seed';
  edition: Edition | null;
  events: EventItem[];
  /** Edition day metadata (titles, descriptions). Added in migration 017. */
  editionDays: EditionDaySnapshot[];
  news: NewsItem[];
  gallery: GalleryItem[];
  sponsors: Sponsor[];
  committee: CommitteeMember[];
  faqs: FAQ[];
  announcements: Announcement[];
  siteSettings: SiteSettingsSnapshot | null;
  /** Phase 6B: published page sections with their items. */
  sections: SectionSnapshot[];
  /** Phase 6B: published past editions for the About page timeline. */
  pastEditions: PastEditionSnapshot[];
}

// Static import — inlined into the main bundle (no extra network request).
// Vite handles JSON imports natively with resolveJsonModule.
import snapshotJson from '../data/generated/snapshot.json';

export const snapshot = snapshotJson as unknown as Snapshot;
